function* naturals() {
  var n = 1;
  while (true) {
    yield n++;
  }
}
function take(iterable, count) {
  var result = [];
  var it = iterable[Symbol.iterator]();
  for (var i = 0; i < count; i++) {
    result.push(it.next().value);
  }
  return result;
}
console.log(take(naturals(), 5));

