  yield;
  console.log('A: step 2');
  yield;
  console.log('A: step 3');
}
function* processB() {
  console.log('B: step 1');
  yield;
  console.log('B: step 2');
}
function runConcurrently(gens) {
  var iterators = gens.map(function (g) {
    return g();
  });
  var done = iterators.map(function () {
    return false;
  });
  while (!done.every(function (d) { return d; })) {
    iterators.forEach(function (it, i) {
      if (!done[i]) {
        var res = it.next();
        if (res.done) done[i] = true;
      }
    });
  }
}
runConcurrently([processA, processB]);

